<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import api from '../../../services/api';import FormErrors from '../../../components/ui/FormErrors.vue';import PlanForm from '../../../components/admin/plans/PlanForm.vue';const router=useRouter(),error=ref(null),busy=ref(false);async function submit(data){busy.value=true;error.value=null;try{const response=await api.post('/v1/platform/plans',data);await router.push({name:'admin.plans.show',params:{id:response.data.data.id},query:{created:1}})}catch(e){error.value=e}finally{busy.value=false}}</script>
<template><div><header class="page-header"><div><RouterLink class="back-link" :to="{name:'admin.plans'}">Back to Subscription Plans</RouterLink><h1 class="mt-3">Create Subscription Plan</h1><p>Configure pricing, resource limits and features for this plan.</p></div></header><FormErrors :error="error"/><PlanForm :busy="busy" @submit="submit" @cancel="router.push({name:'admin.plans'})"/></div></template>
